effect.shader:
void main() {
  vec2 uv = acScreenNorm;

  // Circle/ellipse center
  vec2 center = vec2(centerX, centerY);

  // Apply size scaling to width/height
  vec2 radii = vec2(width, height) * size;

  // Normalized ellipse distance
  vec2 d = (uv - center) / max(radii, vec2(1e-5));
  float dist = length(d);

  // Feathered edge transition
  float edge = smoothstep(1.0, 1.0 - feather, dist);

  if (invert) edge = 1.0 - edge;

  // Sample texture and apply alpha mask
  vec4 tex = texture2DCv(inputImg.texture, uv);
  gl_FragColor = vec4(tex.rgb * edge, tex.a * edge);
}
